// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceHubHostListener {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceHubHostListener] = [UniffiVTableCallbackInterfaceHubHostListener(
        onHubEvent: { (
            uniffiHandle: UInt64,
            event: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeHubHostListener.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onHubEvent(
                     event: try FfiConverterTypeHubHostEvent_lift(event)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterTypeHubHostListener.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface HubHostListener: handle missing in uniffiFree")
            }
        }
    )]
}

private func uniffiCallbackInitHubHostListener() {
    uniffi_dspi_hub_fn_init_callback_vtable_hubhostlistener(UniffiCallbackInterfaceHubHostListener.vtable)
}


