/**
 * A paired client.
 */
public struct HubClient {
    /**
     * Its id.
     */
    public var cid: UInt32
    /**
     * The name it gave.
     */
    public var name: String
    /**
     * Its role.
     */
    public var role: HubClientRole
    /**
     * When it paired, seconds since the epoch.
     */
    public var created: UInt64
    /**
     * When it last signed in, seconds since the epoch.
     */
    public var lastSeen: UInt64?
    /**
     * It has a session now (false with no hub running).
     */
    public var online: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Its id.
         */cid: UInt32, 
        /**
         * The name it gave.
         */name: String, 
        /**
         * Its role.
         */role: HubClientRole, 
        /**
         * When it paired, seconds since the epoch.
         */created: UInt64, 
        /**
         * When it last signed in, seconds since the epoch.
         */lastSeen: UInt64?, 
        /**
         * It has a session now (false with no hub running).
         */online: Bool) {
        self.cid = cid
        self.name = name
        self.role = role
        self.created = created
        self.lastSeen = lastSeen
        self.online = online
    }
}

#if compiler(>=6)
extension HubClient: Sendable {}
#endif


extension HubClient: Equatable, Hashable {
    public static func ==(lhs: HubClient, rhs: HubClient) -> Bool {
        if lhs.cid != rhs.cid {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.role != rhs.role {
            return false
        }
        if lhs.created != rhs.created {
            return false
        }
        if lhs.lastSeen != rhs.lastSeen {
            return false
        }
        if lhs.online != rhs.online {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(cid)
        hasher.combine(name)
        hasher.combine(role)
        hasher.combine(created)
        hasher.combine(lastSeen)
        hasher.combine(online)
    }
}



