/**
 * Why a hub call did not happen. Each says what to show.
 */
public enum HubHostError: Swift.Error {

    
    
    /**
     * An argument was not usable.
     */
    case Invalid(
        /**
         * What was wrong.
         */msg: String
    )
    /**
     * A hub is already running: stop it first.
     */
    case Running
    /**
     * No hub is running.
     */
    case NotRunning
    /**
     * Called from the listener, where it would wait for itself.
     */
    case InCallback
    /**
     * This hub lets anyone in, so there is nothing to pair.
     */
    case OpenAccess
    /**
     * The hub has stopped.
     */
    case Stopped(
        /**
         * The hub's words.
         */msg: String
    )
    /**
     * No such device.
     */
    case NoDevice(
        /**
         * The hub's words.
         */msg: String
    )
    /**
     * That device is attached already.
     */
    case AlreadyAttached(
        /**
         * The hub's words.
         */msg: String
    )
    /**
     * No handle is free.
     */
    case NoHandle(
        /**
         * The hub's words.
         */msg: String
    )
    /**
     * The device's identity could not be read.
     */
    case Identity(
        /**
         * The hub's words.
         */msg: String
    )
    /**
     * An app is already on this hub.
     */
    case AppAttached(
        /**
         * The hub's words.
         */msg: String
    )
    /**
     * The system said no: a port in use, a store that cannot be written, no random
     * numbers.
     */
    case Io(
        /**
         * The hub's words.
         */msg: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeHubHostError: FfiConverterRustBuffer {
    typealias SwiftType = HubHostError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> HubHostError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Invalid(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Running
        case 3: return .NotRunning
        case 4: return .InCallback
        case 5: return .OpenAccess
        case 6: return .Stopped(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 7: return .NoDevice(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 8: return .AlreadyAttached(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 9: return .NoHandle(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 10: return .Identity(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 11: return .AppAttached(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 12: return .Io(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: HubHostError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Invalid(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case .Running:
            writeInt(&buf, Int32(2))
        
        
        case .NotRunning:
            writeInt(&buf, Int32(3))
        
        
        case .InCallback:
            writeInt(&buf, Int32(4))
        
        
        case .OpenAccess:
            writeInt(&buf, Int32(5))
        
        
        case let .Stopped(msg):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .NoDevice(msg):
            writeInt(&buf, Int32(7))
